// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Initially owner is address(0), so we need to transfer ownership first
        // But onlyOwner modifier requires msg.sender == owner, so we prank as address(0)
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        // Now call owned() as the new owner
        vm.prank(newOwner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(success);
    }
}

